#include <stdio.h>
#include <stdlib.h>

// Function to calculate GCD using Euclidean algorithm
long gcd(long a, long b) {
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

// Function to calculate LCM
long lcm(long a, long b) {
    return (a * b) / gcd(a, b);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 1;
    }
    char *endptr;
    long num1 = strtol(argv[1], &endptr, 10);
    long num2 = strtol(argv[2], &endptr, 10);
    if (num1 == 0 && num2 == 0) {
        printf("gcd=0 lcm=0\n");
    } else {
        long g = gcd(num1, num2);
        long l = lcm(num1, num2);
        printf("gcd=%ld lcm=%ld\n", g, l);
    }
    return 0;
}
